import{_ as c,C as r,o as l,c as d,a5 as s,E as t,j as a,a as i,b as B,w as o,a6 as u}from"./chunks/framework.D_J2JZBr.js";const C=JSON.parse('{"title":"模拟/混合信号与生物医疗芯片","description":"从模拟接口到脑机接口与植入式芯片，理解上科大的混合信号研究入口。","frontmatter":{"title":"模拟/混合信号与生物医疗芯片","description":"从模拟接口到脑机接口与植入式芯片，理解上科大的混合信号研究入口。"},"headers":[],"relativePath":"explore-ic/research-directions/analog-mixed.md","filePath":"explore-ic/research-directions/analog-mixed.md","lastUpdated":1795531638000}'),A={name:"explore-ic/research-directions/analog-mixed.md"};function g(p,e,m,f,b,_){const n=r("FacultyList"),E=r("CourseTable"),h=r("Mermaid");return l(),d("div",null,[e[1]||(e[1]=s('<h1 id="模拟-混合信号与生物医疗芯片" tabindex="-1">模拟/混合信号与生物医疗芯片 <a class="header-anchor" href="#模拟-混合信号与生物医疗芯片" aria-label="Permalink to &quot;模拟/混合信号与生物医疗芯片&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>现实世界的电压、电流、声音与生理信号是连续变化的，模拟电路负责放大、滤波、驱动和测量，混合信号电路（Mixed-Signal Circuits）则连接连续信号与数字处理。模数转换器（ADC）、数模转换器（DAC）、时钟和传感前端都是典型模块。生物医疗芯片在这些技术之上，还要面对极弱信号、受限能量、长时间稳定性及安全要求。</p><p>核心研究问题包括：</p><ul><li>如何在噪声、带宽、线性度与功耗之间权衡？</li><li>工艺、电源电压和温度变化怎样影响增益、偏置与稳定性？</li><li>生理信号前端如何抑制共模干扰、直流偏移与运动伪迹？</li><li>数字开关噪声、寄生参数与版图失配怎样影响模拟模块？</li><li>植入或穿戴场景下，供能、通信、封装与安全边界如何协同？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>站内师资数据将吕宏鸣及医疗集成电路与微系统实验室（BICML）列为这一方向的主要入口，公开研究重点是数模混合集成电路、脑机接口芯片与植入式医疗芯片。约 2024 年后摩尔中心材料也将实验室定位为数模混合电路设计和医疗电子系统研发。这里适合同时从电路指标和应用信号链理解问题，而不能把医疗应用仅当作普通放大器的背景标签。</p><p>相邻方向同样值得了解：<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/mems-sensors">MEMS 与传感</a> 关注信号的产生与换能，<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/power">电源管理</a> 关心供能与能量转换，<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/rf-em">射频与电磁</a> 则可能涉及无线链路与场作用。这里的关联是知识地图，不代表已建立的课题组合作关系。</p>',8)),t(n,{dir:"analog"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[i("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,"先用电路、信号与模拟电路建立分析能力，再进入模拟集成电路和工程设计；研究生课程与实际项目要求应查看当学期说明。",-1)),t(E,{codes:"EE111,EE150,EE115A,EE112,EE212,EE291I,EE291H"}),e[4]||(e[4]=a("p",null,[a("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115a"},"EE115A 模拟电路"),i(" 与 "),a("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee150"},"EE150 信号与系统"),i(" 分别提供电路级和系统级视角，两者不宜割裂学习。")],-1)),e[5]||(e[5]=a("h2",{id:"知识前置",tabindex:"-1"},[i("知识前置 "),a("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),e[6]||(e[6]=a("p",null,"下图是建议路线，不是正式先修关系；器件模型与概率统计可用于进一步理解噪声和失配。",-1)),(l(),B(u,null,{default:o(()=>[t(h,{id:"mermaid-67",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20B%5B%22EE115A%20%E6%A8%A1%E6%8B%9F%E7%94%B5%E8%B7%AF%22%5D%0A%20%20C%5B%22EE120%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20B%0A%20%20D%5B%22EE150%20%E4%BF%A1%E5%8F%B7%E4%B8%8E%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20E%5B%22EE112%20%E6%A8%A1%E6%8B%9F%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AFI%22%5D%0A%20%20B%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22EE212%20%E6%A8%A1%E6%8B%9F%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AFII%22%5D%0A%20%20E%20--%3E%20G%5B%22EE291I%20%E6%A8%A1%E6%8B%9F%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E5%B7%A5%E7%A8%8B%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20H%5B%22SI140A%20%E6%A6%82%E7%8E%87%E8%AE%BA%E4%B8%8E%E6%95%B0%E7%90%86%E7%BB%9F%E8%AE%A1%22%5D%20--%3E%20I%5B%22%E5%99%AA%E5%A3%B0%E4%B8%8E%E5%A4%B1%E9%85%8D%E5%88%86%E6%9E%90%22%5D%0A%20%20F%20--%3E%20J%5B%22%E6%B7%B7%E5%90%88%E4%BF%A1%E5%8F%B7%E4%B8%8E%E5%8C%BB%E7%96%97%E8%8A%AF%E7%89%87%22%5D%0A%20%20G%20--%3E%20J%0A%20%20I%20--%3E%20J%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Berkeley BWRC、Stanford、UC San Diego，以及清华、复旦的相关电路团队，都是模拟与混合信号论文的重要来源。医疗芯片还需结合生物医学问题选择具体团队。</li><li><strong>产业参照</strong>：Analog Devices、Texas Instruments、STMicroelectronics 的数据转换器、模拟接口与电源产品，适合用数据手册建立规格意识；不是本校合作关系清单。</li><li><strong>会议与期刊</strong>：ISSCC、VLSI Symposium、CICC、JSSC；医疗与生物接口工作也常见于 BioCAS、IEEE Transactions on Biomedical Circuits and Systems（TBioCAS）。</li></ul><p>比较电路时先统一带宽、输入幅度、负载、电源与工艺条件。对脑机接口而言，电路噪声和功耗只是部分指标，不能据此推断临床有效性或人体使用安全。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/resources">模拟自学</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/">模拟学习地图</a>：安排小信号模型、反馈、频率响应和版图知识。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/fundamentals/">基础自学</a>：补信号系统、概率与数学基础。</li><li><a href="https://www.analog.com/" target="_blank" rel="noreferrer">Analog Devices</a> 与 <a href="https://www.ti.com/" target="_blank" rel="noreferrer">Texas Instruments</a>：从官方教程和数据手册理解真实规格。</li><li><a href="https://sscs.ieee.org/" target="_blank" rel="noreferrer">IEEE Solid-State Circuits Society</a>：查找固态电路领域的教育资源与会议入口。</li></ul><p>可以从一个简单放大器开始，依次检查直流工作点、增益带宽、稳定性、噪声和参数变化，再解释为什么加入寄生参数后表现改变。人体连接实验必须遵循实验室安全和伦理要求。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎相关课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开电路训练与进组准备建议；不收集患者数据、人体实验细节或未公开芯片信息。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/lvhm/main.htm" target="_blank" rel="noreferrer">吕宏鸣学院主页</a>、<a href="https://bicml.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">BICML</a>：公开研究方向与实验室入口。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年材料，不代表当前招生信息。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：具体开课以教务系统为准。</li></ul>',10))])}const S=c(A,[["render",g]]);export{C as __pageData,S as default};
